extern "C" float sqrtf(float);

struct vector3d {
  float x, y, z;
  vector3d() {}
  vector3d(float X, float Y, float Z) : x(X), y(Y), z(Z) {}
  vector3d operator+(const vector3d& v) const { return vector3d(x+v.x,y+v.y,z+v.z); }
  vector3d operator-(const vector3d& v) const { return vector3d(x-v.x,y-v.y,z-v.z); }
  vector3d operator*(float f) const { return vector3d(x*f,y*f,z*f); }
  vector3d operator/(float f) const { float inv=1.0f/f; return vector3d(x*inv,y*inv,z*inv); }
  float length2() const { return x*x+y*y+z*z; }
  float length() const { return sqrtf(length2()); }
  void set_length(float f) { float l2=length2(); if (l2>1.0e-10f) { float s=f/sqrtf(l2); x*=s; y*=s; z*=s; } }
};
inline vector3d cross(const vector3d& a,const vector3d& b) { return vector3d(a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x); }
struct color32 { unsigned int i; };
struct po { char pad[48]; vector3d position; const vector3d& get_position() const { return position; } };
struct camera { char pad[80]; po* abs_po; const po& get_abs_po() const { return *abs_po; } };
struct game { char pad[40]; camera* current_view_camera; camera* get_current_view_camera() { return current_view_camera; } };
struct app { char pad[16]; game* the_game; static app* inst(); game* get_game() { return the_game; } };
extern app* g_app __asm__("app_inst");
__asm__(".equ app_inst,0x0045AC18");
inline app* app::inst() { return g_app; }
void render_quad(const vector3d&,const vector3d&,const vector3d&,const vector3d&,color32,bool=false) __asm__("render_quad__FRC8vector3dN30G7color32b");
__asm__(".equ render_quad__FRC8vector3dN30G7color32b,0x002C8280");

void render_beam( const vector3d &pt1, const vector3d &pt2, color32 col, float thickness )
{
  vector3d vec = pt2 - pt1;
  float len = vec.length();
  if (len<1e-9f)
    return;
  vector3d normvec = vec/len;
  camera* curcam = app::inst()->get_game()->get_current_view_camera();
  vector3d linevec = (pt1+pt2)*0.5f-curcam->get_abs_po().get_position();
  vector3d cx = cross(linevec, normvec);
  if (cx.length2()<1e-9f) return;
  cx.set_length(thickness*0.5f);
  vector3d p0,p1,p2,p3;
  p0 = pt1 - cx;
  p1 = pt1 + cx;
  p2 = pt2 + cx;
  p3 = pt2 - cx;
  render_quad(p0,p1,p2,p3, col);
}
